import{_ as r,o as s,c as o,a3 as e,j as t}from"./chunks/framework.Cc-oPviL.js";const b=JSON.parse('{"title":"01 · Agent 是什么：会用工具的大模型","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agent/01.md","filePath":"ai/agent/01.md"}'),l={name:"ai/agent/01.md"};function n(d,a,i,h,g,c){return s(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="_01-·-agent-是什么-会用工具的大模型" tabindex="-1">01 · Agent 是什么：会用工具的大模型 <a class="header-anchor" href="#_01-·-agent-是什么-会用工具的大模型" aria-label="Permalink to &quot;01 · Agent 是什么：会用工具的大模型&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>Agent = 大模型 + 工具 + 循环：模型负责决定「下一步做什么」，程序负责去执行。</li><li>Agent 和普通聊天、固定流程（Workflow）的区别。</li><li>什么任务适合用 Agent，什么任务不适合。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>前面学的 RAG 是「固定两步」：先查，再答。但很多任务没法提前写死步骤，比如「帮我比较三家公司的财报并写总结」：要查几次、查什么，得边做边决定。</p><p>这就是 Agent 要解决的问题。本篇讲 4 个点：① Agent 的组成 → ② 一个任务的完整循环 → ③ 为什么这么设计 → ④ Agent vs Workflow，什么时候用。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>Agent（智能体）= 让大模型当「大脑」，自己决定调用哪些工具、调用几次，直到把任务完成。</strong></p><h2 id="生活类比-带着手机的实习生" tabindex="-1">生活类比：带着手机的实习生 <a class="header-anchor" href="#生活类比-带着手机的实习生" aria-label="Permalink to &quot;生活类比：带着手机的实习生&quot;">​</a></h2><ul><li><strong>普通聊天的大模型</strong> = 一个博学但<strong>被关在房间里</strong>的人：只能凭记忆回答，不能查、不能动手。</li><li><strong>Agent</strong> = 给他一部手机（<strong>工具</strong>：能搜索、能算、能发邮件），让他<strong>自己判断</strong>下一步该干什么，干完看结果，再决定下一步。</li><li>但手机里每个 App 都是<strong>你装的、你授权的</strong>：他只能用你给的工具。</li></ul><h2 id="一步步看-「明天北京要不要带伞-」" tabindex="-1">一步步看：「明天北京要不要带伞？」 <a class="header-anchor" href="#一步步看-「明天北京要不要带伞-」" aria-label="Permalink to &quot;一步步看：「明天北京要不要带伞？」&quot;">​</a></h2>',10),t("figure",{class:"fig"},[t("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),t("svg",{viewBox:"0 0 680 290",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"Agent 循环图"},[t("defs",null,[t("marker",{id:"arw-agent",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto"},[t("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),t("rect",{class:"f-box",x:"20",y:"110",width:"110",height:"56",rx:"8"}),t("text",{class:"f-title",x:"75.0",y:"134.0","text-anchor":"middle"},"用户任务"),t("text",{class:"f-label",x:"75.0",y:"152.0","text-anchor":"middle"},"「查明天北京天气」"),t("rect",{class:"f-box-hi",x:"190",y:"40",width:"150",height:"56",rx:"8"}),t("text",{class:"f-title",x:"265.0",y:"64.0","text-anchor":"middle"},"思考 Thought"),t("text",{class:"f-label",x:"265.0",y:"82.0","text-anchor":"middle"},"下一步该干嘛？"),t("rect",{class:"f-box",x:"400",y:"40",width:"150",height:"56",rx:"8"}),t("text",{class:"f-title",x:"475.0",y:"64.0","text-anchor":"middle"},"行动 Action"),t("text",{class:"f-label",x:"475.0",y:"82.0","text-anchor":"middle"},"调用 get_weather"),t("rect",{class:"f-box",x:"400",y:"180",width:"150",height:"56",rx:"8"}),t("text",{class:"f-title",x:"475.0",y:"204.0","text-anchor":"middle"},"观察 Observation"),t("text",{class:"f-label",x:"475.0",y:"222.0","text-anchor":"middle"},"返回：晴，12℃"),t("rect",{class:"f-box",x:"190",y:"180",width:"150",height:"56",rx:"8"}),t("text",{class:"f-title",x:"265.0",y:"204.0","text-anchor":"middle"},"判断"),t("text",{class:"f-label",x:"265.0",y:"222.0","text-anchor":"middle"},"够回答了吗？"),t("rect",{class:"f-box-alt",x:"560",y:"110",width:"100",height:"56",rx:"8"}),t("text",{class:"f-title",x:"610.0",y:"143.0","text-anchor":"middle"},"最终回答"),t("path",{class:"f-line",d:"M130 128 C160 128 160 68 186 68","marker-end":"url(#arw-agent)"}),t("path",{class:"f-line",d:"M340 68 H396","marker-end":"url(#arw-agent)"}),t("path",{class:"f-line",d:"M475 96 V176","marker-end":"url(#arw-agent)"}),t("path",{class:"f-line",d:"M400 208 H344","marker-end":"url(#arw-agent)"}),t("path",{class:"f-line f-dash",d:"M265 180 V100","marker-end":"url(#arw-agent)"}),t("text",{class:"f-label",x:"272",y:"146"},"不够 → 再想一轮"),t("path",{class:"f-line-hi",d:"M340 222 C470 270 600 250 610 170","marker-end":"url(#arw-agent)"}),t("text",{class:"f-label",x:"470",y:"276"},"够了 → 输出"),t("text",{class:"f-label",x:"560",y:"30"},"工具由程序执行，"),t("text",{class:"f-label",x:"560",y:"46"},"不是模型自己执行")]),t("figcaption",{class:"fig-cap"},"Agent = 大模型 + 工具 + 循环。模型每轮只做一件事：决定「下一步调哪个工具、参数是什么」；真正执行工具的是外面的程序，结果再喂回给模型。循环到模型认为信息够了，才输出最终回答。")],-1),e('<p>可用工具：<code>get_weather(city, date)</code>（查天气）。</p><table tabindex="0"><thead><tr><th>轮次</th><th>谁在做</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td><strong>模型思考</strong></td><td>要回答带不带伞，得先知道明天北京的天气</td></tr><tr><td>1</td><td><strong>模型决定行动</strong></td><td>调用 <code>get_weather(city=&quot;北京&quot;, date=&quot;明天&quot;)</code></td></tr><tr><td>1</td><td><strong>程序执行</strong></td><td>真的去调天气接口，拿到「小雨，降水概率 80%」</td></tr><tr><td>1</td><td><strong>结果喂回模型</strong></td><td>观察（Observation）：小雨，80%</td></tr><tr><td>2</td><td><strong>模型思考</strong></td><td>信息够了</td></tr><tr><td>2</td><td><strong>模型输出</strong></td><td>「明天北京有小雨，降水概率 80%，建议带伞。」</td></tr></tbody></table><p>关键点：<strong>模型自己从不执行任何东西</strong>。它只是输出一段「我想调用 get_weather，参数是……」，真正去调接口的是外面的程序。</p><h3 id="agent-的四个组成部分" tabindex="-1">Agent 的四个组成部分 <a class="header-anchor" href="#agent-的四个组成部分" aria-label="Permalink to &quot;Agent 的四个组成部分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组成</th><th>作用</th><th>例子</th></tr></thead><tbody><tr><td><strong>大模型（大脑）</strong></td><td>理解任务、决定下一步</td><td>GPT、Claude、通义千问等</td></tr><tr><td><strong>工具（手脚）</strong></td><td>和外部世界交互</td><td>搜索、查数据库、执行代码、发邮件</td></tr><tr><td><strong>循环（流程）</strong></td><td>想 → 做 → 看结果 → 再想</td><td>直到完成，或达到最大轮数</td></tr><tr><td><strong>记忆（笔记本）</strong></td><td>记住之前做了什么</td><td>对话历史、存到外部的长期笔记</td></tr></tbody></table><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么需要-agent-只用大模型不行吗" tabindex="-1">为什么需要 Agent？只用大模型不行吗？ <a class="header-anchor" href="#为什么需要-agent-只用大模型不行吗" aria-label="Permalink to &quot;为什么需要 Agent？只用大模型不行吗？&quot;">​</a></h3><ul><li><strong>问题</strong>：大模型只能生成文字，不能查实时信息、不能操作系统；而且复杂任务的步骤没法提前写死。</li><li><strong>方案</strong>：给模型一组工具，让它在循环里自己决定调用哪个、调用几次。</li><li><strong>好处</strong>：能完成多步骤、需要和外部交互的任务，比如查资料、分析数据、执行操作。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>大模型只会生成文字、不能获取实时信息和执行操作；Agent 让模型在循环中自主选择并调用工具，从而完成多步骤、需要和外部交互的任务。</p></div><h3 id="为什么工具由程序执行-而不是模型直接执行" tabindex="-1">为什么工具由程序执行，而不是模型直接执行？ <a class="header-anchor" href="#为什么工具由程序执行-而不是模型直接执行" aria-label="Permalink to &quot;为什么工具由程序执行，而不是模型直接执行？&quot;">​</a></h3><ul><li><strong>问题</strong>：如果模型能直接执行任意操作，一次误判或被诱导，就可能删库、乱发邮件。</li><li><strong>方案</strong>：模型只输出「想做什么」，程序检查参数、确认权限后再执行。</li><li><strong>好处</strong>：所有动作都可以检查、记录、拦截；危险操作可以要求人工确认。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>模型只负责决策、程序负责执行，中间可以加参数校验、权限控制和人工确认，Agent 才可控、可审计。</p></div><h3 id="为什么要设置最大轮数" tabindex="-1">为什么要设置最大轮数？ <a class="header-anchor" href="#为什么要设置最大轮数" aria-label="Permalink to &quot;为什么要设置最大轮数？&quot;">​</a></h3><ul><li><strong>问题</strong>：模型可能反复调用同一个工具，或者在两步之间来回打转，停不下来，白白花钱。</li><li><strong>方案</strong>：限制最多循环 N 轮（比如 10 轮），超过就停下并报告。</li><li><strong>好处</strong>：防止死循环和费用失控。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>防止模型陷入重复调用或无效循环，控制成本和延迟。</p></div><h2 id="agent-vs-workflow-什么时候用哪个" tabindex="-1">Agent vs Workflow：什么时候用哪个 <a class="header-anchor" href="#agent-vs-workflow-什么时候用哪个" aria-label="Permalink to &quot;Agent vs Workflow：什么时候用哪个&quot;">​</a></h2><p><strong>Workflow（工作流）</strong>：步骤是<strong>人提前写死</strong>的，比如 RAG 的「检索 → 生成」。</p><table tabindex="0"><thead><tr><th></th><th>Workflow</th><th>Agent</th></tr></thead><tbody><tr><td>步骤谁定</td><td>开发者提前写好</td><td>模型运行时决定</td></tr><tr><td>可预测性</td><td>高，每次都一样</td><td>低，每次可能不同</td></tr><tr><td>成本和速度</td><td>低、快</td><td>高、慢（多轮调用模型）</td></tr><tr><td>适合</td><td>步骤固定的任务</td><td>步骤不确定、需要探索的任务</td></tr></tbody></table><p><strong>选择原则</strong>：<strong>能用固定流程解决的，就别用 Agent。</strong> Agent 更灵活，但也更贵、更慢、更难调试。先用最简单的方案，确实不够再加自主性。</p><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Agent</td><td>agent 代理人、行动者</td><td>能自主决定并调用工具完成任务的 AI 系统</td></tr><tr><td>Tool</td><td>工具</td><td>Agent 可调用的外部能力，如搜索、计算</td></tr><tr><td>Action</td><td>act 行动 + -ion</td><td>行动：调用某个工具</td></tr><tr><td>Observation</td><td>observe 观察 + -ation</td><td>观察：工具返回的结果</td></tr><tr><td>Workflow</td><td>work 工作 + flow 流程</td><td>工作流：提前写死步骤的流程</td></tr><tr><td>Autonomy</td><td>auto 自己 + nomy 规则</td><td>自主性：自己决定怎么做的程度</td></tr><tr><td>Max Iterations</td><td>max 最大 + iterations 迭代次数</td><td>最大循环轮数</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：什么是 Agent？和普通的 LLM 调用有什么区别？</strong></p><blockquote><p>Agent 是以大模型为决策核心，结合工具调用、循环执行和记忆的系统。普通调用是一问一答；Agent 会根据任务自主规划步骤，多轮调用工具获取信息或执行操作，根据结果调整下一步，直到完成。</p></blockquote><p><strong>Q：Agent 和 Workflow 怎么选？</strong></p><blockquote><p>步骤固定、可预测的任务用 Workflow，稳定、便宜、好调试；步骤不确定、需要根据中间结果决定后续操作的任务才用 Agent。实践中常常是 Workflow 为主，在个别环节引入 Agent。</p></blockquote><p><strong>Q：Agent 一般由哪几部分组成？</strong></p><blockquote><p>大模型（规划和决策）、工具（与外部交互）、执行循环（感知 → 决策 → 行动 → 观察）、记忆（短期上下文和长期存储）。有的还会单独列出规划模块。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>「模型调用了工具」不严谨</strong>：准确说法是模型<strong>生成了调用请求</strong>，由程序执行。</li><li><strong>Agent 不是越自主越好</strong>：自主性越高，越不可控。生产环境通常加很多约束：限定工具、限定轮数、关键操作人工确认。</li><li><strong>RAG 和 Agent 不对立</strong>：「检索知识库」可以作为 Agent 的一个工具，这种叫 Agentic RAG。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/rag/01">RAG 是什么</a>：RAG 是固定流程；Agent 让模型自己决定什么时候查、查什么。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/02">工具调用</a>：模型是怎么「说出」要调哪个工具的。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/03">ReAct 与规划</a>：循环里「想」和「做」怎么交替。</li><li><strong>类比</strong> <a href="/study-hub/bagu/os/03">调度与并发同步</a>：操作系统调度进程、Agent 调度工具，都在决定「下一步让谁干」。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：Agent 由哪几部分组成？用「实习生」类比说一下。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>大模型是<strong>大脑</strong>（判断下一步做什么），工具是<strong>手机里的 App</strong>（能查、能算、能发消息），循环是<strong>做事流程</strong>（想 → 做 → 看结果 → 再想），记忆是<strong>笔记本</strong>（记住做过什么）。</p></details><p><strong>Q2：在 Agent 里，工具是谁执行的？为什么这样设计？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>外面的程序</strong>执行，模型只输出「想调哪个工具、参数是什么」。这样中间可以做参数校验、权限控制和人工确认，所有动作都可检查、可拦截、可记录。</p></details><p><strong>Q3：「每天把销售数据汇总成固定格式的日报」适合用 Agent 吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>不太适合</strong>。步骤固定（取数 → 汇总 → 套模板），用固定流程（Workflow）更稳定、便宜、好调试。Agent 适合步骤不确定、要根据中间结果决定下一步的任务。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出 Agent 的四个组成部分，并用类比解释</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能讲清「查天气」例子里每一轮谁在做什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说清工具为什么由程序执行（问题 → 方案 → 好处）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能对比 Agent 和 Workflow，并给出「什么时候用哪个」的原则</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释为什么要设置最大轮数</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>模型是怎么用结构化的方式「说」出要调哪个工具的？→ <a href="/study-hub/ai/agent/02">工具调用 Function Calling</a></li></ul>',43)])])}const x=r(l,[["render",n]]);export{b as __pageData,x as default};
